const items = $input.all();

// Extract data from merged inputs
const stats = items.find(item => item.json.last_analysis_stats);
const analysis = items.find(item => item.json.content);
const enrichmentItem = items.find(item => item.json.enrichment);

// Get enrichment data
const enrichment = enrichmentItem?.json?.enrichment || {};

return [{
  json: {
    // VirusTotal stats
    virustotal_stats: stats?.json.last_analysis_stats || [{
      malicious: 0, suspicious: 0, harmless: 0, undetected: 0, timeout: 0
    }],

    // AbuseIPDB data
    abuseipdb: enrichment.abuseipdb || {
      confidence_score: 0,
      total_reports: 0,
      isp: 'N/A',
      usage_type: 'N/A'
    },

    // Combined threat assessment
    combined_threat_score: enrichment.combined_threat_score || 0,
    threat_level: enrichment.threat_level || 'UNKNOWN',

    // Log analysis
    log_analysis: analysis?.json.content || "No analysis available",

    // Original alert data
    body: stats?.json.body || analysis?.json.body
  }
}];

