}

// Helper function to detect OS from Wazuh alert
function detectOS(alertData, isFullAlert) {
  // Try to get OS from agent.os field (MOST RELIABLE)
  const agentOS = isFullAlert 
    ? alertData.body.full_alert?.agent?.os?.platform || alertData.body.full_alert?.agent?.os?.name
    : alertData.body.agent?.os?.platform || alertData.body.agent?.os?.name;

  if (agentOS) {
    const os = agentOS.toLowerCase();
    if (os.includes('windows')) return 'windows';
    if (os.includes('linux')) return 'linux';
    if (os.includes('darwin') || os.includes('macos') || os.includes('mac os')) return 'macos';
  }

  // Try decoder field
  const decoder = isFullAlert 
    ? alertData.body.full_alert?.decoder?.name
    : alertData.body.decoder?.name;

  if (decoder) {
    const dec = decoder.toLowerCase();
    if (dec.includes('windows') || dec.includes('eventchannel') || dec.includes('eventlog')) return 'windows';
    if (dec.includes('syslog') || dec.includes('linux')) return 'linux';
    if (dec.includes('macos') || dec.includes('darwin')) return 'macos';
  }

  // Try to detect from predecoder.program_name
  const programName = isFullAlert 
    ? alertData.body.full_alert?.predecoder?.program_name
    : alertData.body.predecoder?.program_name;

  if (programName) {
    const program = programName.toLowerCase();

    // Windows indicators
    if (program.includes('microsoft-windows') || 
        program.includes('svchost') || 
        program.includes('system32') ||
        program.includes('windows') ||
        program === 'system' ||
        program === 'security' ||
        program === 'application' ||
        program === 'wineventlog' ||
        program.includes('powershell') ||
        program.includes('mssql') ||
        program.includes('iis') ||
        program.includes('winlogon') ||
        program.includes('lsass') ||
        program.includes('services.exe')) {
      return 'windows';
    }

    // Linux indicators
    if (program === 'sshd' || 
        program === 'sudo' || 
        program === 'systemd' ||
        program === 'kernel' ||
        program === 'cron' ||
        program === 'apache2' ||
        program === 'nginx' ||
        program === 'postfix' ||
        program === 'dovecot' ||
        program === 'vsftpd' ||
        program === 'auditd' ||
        program === 'rsyslogd' ||
        program === 'dbus' ||
        program === 'polkitd' ||
        program === 'firewalld' ||
        program === 'named' ||
        program === 'dhcpd' ||
        program === 'mysql' ||
        program === 'postgresql') {
      return 'linux';
    }

    // macOS indicators
    if (program.includes('com.apple.') ||
        program === 'launchd' ||
        program === 'securityd' ||
        program === 'installd' ||
        program.includes('cfprefsd')) {
      return 'macos';
    }
  }

  // Try to detect from full_log content
  const fullLog = isFullAlert 
    ? alertData.body.full_alert?.full_log
    : alertData.body.full_log;

  if (fullLog) {
    const log = fullLog.toLowerCase();

    // Windows patterns
    if (log.includes('c:\\windows') || 
        log.includes('c:\\program files') ||
        log.includes('\\windows\\') ||
        log.includes('eventlog') || 
        log.includes('microsoft-windows') ||
        log.includes('.exe') ||
        log.includes('.dll') ||
        log.includes('hkey_') ||
        log.includes('registry') ||
        log.includes('\\system32\\') ||
        log.includes('\\syswow64\\') ||
        log.includes('eventchannel') ||
        log.includes('powershell.exe') ||
        log.includes('cmd.exe') ||
        log.includes('taskmgr') ||
        log.match(/[a-z]:\\/i)) {  // Drive letter pattern
      return 'windows';
    }

    // Linux patterns
    if (log.includes('/var/log') || 
        log.includes('/etc/') || 
        log.includes('/usr/') ||
        log.includes('/home/') ||
        log.includes('/root/') ||
        log.includes('/bin/') ||
        log.includes('/sbin/') ||
        log.includes('/opt/') ||
        log.includes('/tmp/') ||
        log.includes('bash') ||
        log.includes('sh:') ||
        log.includes('/dev/') ||
        log.includes('/proc/') ||
        log.includes('/sys/') ||
        log.includes('systemctl') ||
        log.includes('apt-get') ||
        log.includes('yum install') ||
        log.includes('dnf install') ||
        log.includes('zypper') ||
        log.includes('pacman') ||
        log.includes('systemd[') ||
        log.includes('kernel:')) {
      return 'linux';
    }

    // macOS patterns
    if (log.includes('/library/') || 
        log.includes('/applications/') ||
        log.includes('com.apple.') ||
        log.includes('darwin') ||
        log.includes('/users/') ||
        log.includes('launchd') ||
        log.includes('.app/') ||
        log.includes('/system/library/') ||
        log.includes('brew install') ||
        log.includes('osascript')) {
      return 'macos';
    }
  }

  // Check rule groups (some rules are OS-specific)
  const ruleGroups = isFullAlert 
    ? alertData.body.full_alert?.rule?.groups
    : alertData.body.rule?.groups;

  if (ruleGroups && Array.isArray(ruleGroups)) {
    const groups = ruleGroups.join(',').toLowerCase();
    if (groups.includes('windows')) return 'windows';
    if (groups.includes('linux')) return 'linux';
    if (groups.includes('macos') || groups.includes('mac')) return 'macos';
  }

  // Check syscheck (file integrity monitoring) paths
  const syscheckPath = isFullAlert 
    ? alertData.body.full_alert?.syscheck?.path
    : alertData.body.syscheck?.path;

  if (syscheckPath) {
    const path = syscheckPath.toLowerCase();
    if (path.includes('c:\\') || path.includes('\\windows\\')) return 'windows';
    if (path.startsWith('/') && !path.includes('/library/') && !path.includes('/applications/')) return 'linux';
    if (path.includes('/library/') || path.includes('/applications/')) return 'macos';
  }

  // Check location field (some Wazuh integrations include this)
  const location = isFullAlert 
    ? alertData.body.full_alert?.location
    : alertData.body.location;

  if (location) {
    const loc = location.toLowerCase();
    if (loc.includes('eventchannel') || loc.includes('eventlog')) return 'windows';
    if (loc.includes('syslog') || loc.includes('/var/log')) return 'linux';
    if (loc.includes('macos.log') || loc.includes('unified.log')) return 'macos';
  }

  return 'unknown';
}

// Check if data is under body.full_alert or directly under body
